/// <summary>
/// Find corresponding METSalesLine (additional fields).
/// </summary>
/// <returns>METSalesLine record</returns>
public METSalesLine metSalesLine()
{
    return this.SysExtensionSerializerMap::getExtensionTable(tableNum(METSalesLine));
}

/// <summary>
/// pack the METSalesLine record fields
/// </summary>
/// <param name = "_metSalesLine">Record buffer of METSalesLine to pack</param>
public void metPackMETSalesLine(METSalesLine _metSalesLine)
{
    _metSalesLine.SalesLine = this.RecId;
    this.SysExtensionSerializerMap::packExtensionTable(_metSalesLine);
}

    /// <summary>
    /// Inserts a table buffer into the database.
    /// </summary>
    /// <param name = "_dropInvent">_dropInvent</param>
    /// <param name = "_findMarkup">_findMarkup</param>
    /// <param name = "_childBuffer">_childBuffer</param>
    /// <param name = "_skipCreditLimitCheck">_skipCreditLimitCheck</param>
    /// <param name = "_skipWHSProcesses">_skipWHSProcesses</param>
    /// <param name = "_interCompanyInventTransId">_interCompanyInventTransId</param>
    public void insert(boolean     _dropInvent,
                        boolean     _findMarkup,
                        Common      _childBuffer,
                        boolean     _skipCreditLimitCheck,
                        boolean     _skipWHSProcesses,
                        InventRefTransId _interCompanyInventTransId)
    {
        METSalesLine            metSalesLine;

        next insert(_dropInvent, _findMarkup, _childBuffer, _skipCreditLimitCheck, _skipWHSProcesses, _interCompanyInventTransId );

        metSalesLine = this.metSalesLine();

        // CB173 Sales Order Extract Screen V2 - refactor
        this.metSetSalesUnitFields(metsalesLine);
        this.metSetActualUnitFields(metsalesLine);
    
        if (metSalesLine.RecId == 0)
        {
            this.metPackMETSalesLine(metSalesLine);
            this.SysExtensionSerializerMap::postInsert();
        }
    }

    /// <summary>
    /// Updates a table buffer into the database.
    /// </summary>
    /// <param name = "_dropInvent">_dropInvent</param>
    /// <param name = "_childBuffer">_childBuffer</param>
    /// <param name = "_updateOrderLineOfDeliverySchedule">_updateOrderLineOfDeliverySchedule</param>
    /// <param name = "_mcrAutoallocate">_mcrAutoallocate</param>
    /// <param name = "_cameFromCreate">_cameFromCreate</param>
    /// <param name = "_promptSuppItem">_promptSuppItem</param>
    public void update(boolean  _dropInvent,
                        Common   _childBuffer,
                        boolean  _updateOrderLineOfDeliverySchedule,
                        boolean  _mcrAutoallocate,
                        boolean  _cameFromCreate,
                        boolean  _promptSuppItem)
    {
        boolean         updateSalesUnitFields;
        METSalesLine    metSalesLineUpdate;
        SalesLine       salesLineOrig = this.orig();

        if (this.SalesUnit != salesLineOrig.SalesUnit
    ||  this.InventDimId != salesLineOrig.InventDimId)
        {
            updateSalesUnitFields = true;
        }

        next update(_dropInvent, _childBuffer, _updateOrderLineOfDeliverySchedule, _mcrAutoallocate, _cameFromCreate, _promptSuppItem);

        if (updateSalesUnitFields)
        {
            ttsbegin;
            metSalesLineUpdate = this.metSalesLine();
            metSalesLineUpdate.selectForUpdate(true);
    
            // CB173 Sales Order Extract Screen V2 - refactor
            this.metSetSalesUnitFields(metSalesLineUpdate);
            metSalesLineUpdate.update();
            ttscommit;
        }

        this.SysExtensionSerializerMap::postUpdate();
    }

    /// <summary>
    /// Get InventTable buffer related to the SalesLine with limited fields
    /// </summary>
    /// <returns>InventTable buffer with limited fields</returns>
    [SysClientCacheDataMethodAttribute(true)]
    public InventTable metInventTableLimitedFields()
    {
        InventTable     metInventTableLimitedFields;
        select firstonly Product, NetWeight, TaraWeight, UnitVolume
            from metInventTableLimitedFields
            where metInventTableLimitedFields.ItemId == this.ItemId;

        return metInventTableLimitedFields;
    }

