/// <returns>unitVolume of salesLine Item</returns>
[SysClientCacheDataMethodAttribute(true)]
public display METUOMVolume displayMETUnitVolume()
{
    return METWHSPhysDimUOMSite::convertVolume(this.ItemId, this.SalesQty, this.SalesUnit, this.inventDim());
}

    /// <summary>
    /// To get ActualUnitVolume for the SalesLine Item.
    /// </summary>
    /// <returns>unitVolume of salesLine Item</returns>
    [SysClientCacheDataMethodAttribute(true)]
    public display METUOMVolume displayMETActualUnitVolume()
    {
        
        InventQty               actBrokenCase   = this.displayMETActualBrokenCase();
        InventQty               actCase         = this.displayMETActualCases();
        UnitOfMeasureSymbol     unitInvent      = InventTableModule::find(this.itemId, ModuleInventPurchSales::Invent).UnitId;
        UnitOfMeasureSymbol     unitSales       = this.SalesUnit;

        return (METWHSPhysDimUOMSite::convertVolume(this.ItemId, actCase, unitSales, this.inventDim())
                    + METWHSPhysDimUOMSite::convertVolume(this.ItemId, actBrokenCase, unitInvent, this.inventDim()));
    }

/// <summary>
/// Calculate total number of cases for the sales order line quantity.
/// </summary>
/// <returns>Total cases of salesLine Item</returns>
[SysClientCacheDataMethod(true)]
public display InventQty metTotalcases()
{
    return this.SalesUnit == METConstants::unitEach ? 0 : this.SalesQty;
}

    /// <summary>
    /// Calculate actual total number of cases for the sales order line quantity.
    /// </summary>
    /// <returns>Total cases of salesLine Item</returns>
    [SysClientCacheDataMethod(true)]
    public display InventQty metActualTotalcases()
    {
        UnitOfMeasureSymbol     unitInvent          = InventTableModule::find(this.itemId, ModuleInventPurchSales::Invent).UnitId;
        METInventTransView      views;

        select sum(Qty) from views where views.ReferenceId == this.SalesId
                && views.inventTransId == this.InventTransId
                && views.StatusIssue == StatusIssue::ReservPhysical;
        inventqty  reservedQty = (abs(views.Qty));

        Factor factor = EcoResProductUnitConverter::convertForReleasedProduct(
                        this.ItemId,
                        this.inventDimId,
                        1,
                        EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(unitInvent),
                        EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(this.SalesUnit),
                        NoYes::No,
                        NoYes::No);
        
        return this.SalesUnit == METConstants::unitEach ? 0 : (factor * reservedQty);
    }

/// <summary>
/// To calculate and display the number of cases for the sales order line quantity.
/// </summary>
/// <returns>Number of cases</returns>
[SysClientCacheDataMethod(true)]
public display METCase displayMETcases()
{
    return any2Int(this.metTotalcases());
}

/// <summary>
/// To calculate and display the number of cases for the sales order line quantity.
/// </summary>
/// <returns>Number of cases</returns>
[SysClientCacheDataMethod(true)]
public display METCase displayMETActualCases()
{
    return any2Int(this.metActualTotalcases());
}

    /// <summary>
    /// To calculate and display the number of broken cases for the sales order line quantity.
    /// </summary>
    /// <returns>Number of broken cases</returns>
    [SysClientCacheDataMethodAttribute(true)]
    public display METBrokenCase displayMETActualBrokenCase()
    {
        //Show broken case for each line that equals to the ordered quantity for sell units that are in "ea". 
        //For any other sell units broken case=0
        //return this.SalesUnit == METConstants::unitEach ? this.SalesQty : 0;

        UnitOfMeasureSymbol     unitInvent          = InventTableModule::find(this.itemId, ModuleInventPurchSales::Invent).UnitId;
        METInventTransView      views;

        select sum(Qty) from views where views.ReferenceId == this.SalesId
                && views.inventTransId == this.InventTransId
                && views.StatusIssue == StatusIssue::ReservPhysical;
        inventqty  reservedQty = (abs(views.Qty));

        Factor factor = EcoResProductUnitConverter::convertForReleasedProduct(
                        this.ItemId,
                        this.inventDimId,
                        1,
                        EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(unitInvent),
                        EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(this.SalesUnit),
                        NoYes::No,
                        NoYes::No);


        METCase actualCase = any2Int(this.SalesUnit == METConstants::unitEach ? 0 : (factor * reservedQty));
        
        return reservedQty-(actualCase*(1/factor));//this.SalesUnit == METConstants::unitEach ? (factor * reservedQty) : 0;

    }

/// <summary>
/// To calculate and display the number of broken cases for the sales order line quantity.
/// </summary>
/// <returns>Number of broken cases</returns>
[SysClientCacheDataMethodAttribute(true)]
public display METBrokenCase displayMETBrokenCase()
{
    //Show broken case for each line that equals to the ordered quantity for sell units that are in "ea".
    //For any other sell units broken case=0
    return this.SalesUnit == METConstants::unitEach ? this.SalesQty : 0;
}

/// <summary>
/// Copy profit centre dimension  from warehouse
/// </summary>
/// <param name = "_inventDim">InventDIm</param>
public void metCopyDimensionfromWarehosue(InventDim _inventDim = this.inventDim())
{
    DimensionDefault            dimensionWarehouse;
    //Copy dimension from Warehouse if exists
    if (_inventDim.InventLocationId)
    {
        dimensionWarehouse = InventLocation::changeDimension(this.DefaultDimension, _inventDim.InventLocationId);
    }
    DimensionDisplayValue dimensionValue = METHelper::getDimensionValue(dimensionWarehouse, METConstants::profitCentre);
    if(dimensionValue)
    {
        this.DefaultDimension = dimensionWarehouse;
    }
    else
    {
        this.DefaultDimension = InventSite::changeDimension(this.DefaultDimension, _inventDim.InventSiteId);
    }
}

    /// <summary>
    /// Method to determine if conversion exists  between the purchase and warehouse units
    /// </summary>
    /// <param name = "_conversionQty">Qty to convert</param>
    /// <param name = "_itemId">item id</param>
    /// <param name = "_inventDim">InventDim</param>
    /// <returns>True if UOM conversion is found/else false and warehouse unit and the warehouse quantity</returns>
    public static container metGetQtyWeightVolume(Qty _conversionQty, Itemid _itemId, InventDim _inventDim)
    {
        Qty                         reservedQty;
        METCase                     caseQty;
        UnitOfMeasureSymbol         inventoryUnit, warehouseUnit;
        Weight                      weight;
        Volume                      volume;

        InventTableModule           inventTableModule;

        Factor                      factor;

        if(!_inventDim)
        {
            return [1, _conversionQty];
        }

        warehouseUnit = METInventLocation::getWarehouseUnit(_itemId, _inventDim);

        if (warehouseUnit == METConstants::emptyString)
        {
            return [1, _conversionQty];
        }
             
        
        select firstonly UnitId from inventTableModule
            where inventTableModule.ItemId      == _itemId
                && inventTableModule.ModuleType == ModuleInventPurchSales::Invent;

        if(inventTableModule.UnitId)
        {
            inventoryUnit = inventTableModule.UnitId;
        }

        if(inventoryUnit == warehouseUnit)
        {
            caseQty     = 1;
            reservedQty = _conversionQty;
        }
        else
        {
            factor = EcoResProductUnitConverter::convertForReleasedProduct(
                        _itemId,
                        _inventDim.inventDimId,
                        _conversionQty,
                        EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(inventoryUnit),
                        EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(warehouseUnit),
                        NoYes::No,
                        NoYes::No);

            if(factor)
            {
                reservedQty     = factor;
                caseQty = _conversionQty / factor;
            }
        }

        weight  =   METWHSPhysDimUOMSite::convertWeight(_itemId, reservedQty, warehouseUnit, _inventDim);
        volume  =   METWHSPhysDimUOMSite::convertVolume(_itemId, reservedQty, warehouseUnit, _inventDim);

        return [caseQty, reservedQty, weight, volume];
    }

    /// <summary>
    /// Changes the sales line, depending on changes in the sales unit field.
    /// </summary>
    /// <remarks>
    /// Called from the <c>modifiedField</c> method.
    /// </remarks>
    public void salesUnitModified()
    {
        next salesUnitModified();

        InventItemBarcode inventItemBarcode = InventItemBarcode::findSalesBarcodeDimension(this.ItemId,  this.inventDim(), '', this.SalesUnit);

        this.BarCode     = inventItemBarcode.ItemBarCode;
        this.BarCodeType = inventItemBarcode.BarcodeSetupId;
    }

    /// <summary>
    /// Initializes item barcode
    /// </summary>
    /// <param name = "_inventDim">InventDim</param>
    void initBarcode(InventDim _inventDim)
    {
        next initBarcode(_inventDim);

        InventItemBarcode   inventItemBarcode = InventItemBarcode::findSalesBarcodeDimension(this.ItemId, _inventDim, '', this.SalesUnit);

        this.BarCode        = inventItemBarcode.ItemBarCode;
        this.BarCodeType    = inventItemBarcode.BarcodeSetupId;
    }

    /// <summary>
    /// Cancel sales order line
    /// </summary>
    public void metCancelSalesOrderLine()
    {
        ttsbegin;

        this.selectForUpdate(true);
        SalesUpdateRemain::construct().updateDeliverRemainder(this, 0, 0);

        ttscommit;
    }

    /// <summary>
    /// CB173 Sales Order Extract Screen V2 - refactor
    /// </summary>
    void metSetSalesUnitFields(METSalesLine _metSalesLine)
    {
        UnitOfMeasureSymbol     ui  = InventTableModule::find(this.itemId, ModuleInventPurchSales::Invent).UnitId;
        Factor                  factor;
    
        _metSalesLine.SalesUnitWeight = METWHSPhysDimUOMSite::convertWeight(
                            this.ItemId, 1, this.SalesUnit, this.inventDim());
        _metSalesLine.SalesUnitVolume = METWHSPhysDimUOMSite::convertVolume(
                            this.ItemId, 1,  this.SalesUnit, this.inventDim());

        if (ui != this.SalesUnit)
        {
            factor = EcoResProductUnitConverter::convertForReleasedProduct(
                        this.ItemId,
                        this.inventDimId,
                        1,
                        EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(ui),
                        EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(this.SalesUnit),
                        NoYes::No,
                        NoYes::No);
        }
        _metSalesLine.SalesUnitCase = any2Int(this.SalesUnit == METConstants::unitEach ? 0 : (factor));
    }

/// <summary>
/// CB173 Sales Order Extract Screen V2 - refactor
/// </summary>
/// <param name = "_metSalesLine"></param>
void metSetActualUnitFields(METSalesLine _metSalesLine)
{
    UnitOfMeasureSymbol unitInvent  =   InventTableModule::find(this.ItemId, ModuleInventPurchSales::Invent).UnitId;
    _metSalesLine.ActualUnitWeight   =   METWHSPhysDimUOMSite::convertWeight(this.ItemId, 1, unitInvent, this.inventDim());
    _metSalesLine.ActualUnitVolume   =   METWHSPhysDimUOMSite::convertVolume(this.ItemId, 1, unitInvent, this.inventDim());
    _metSalesLine.ActualUnitCase     =   this.displayMETActualCases();
}

/// <summary>
/// CB167_PerformStockReservation.
/// Checks if item status is Active for given item on salesline.
/// </summary>
/// <returns>True, if item status is active; otherwise, false.</returns>
public boolean metCheckItemStatusActive()
{
    return (
        select firstonly RecId from METInventItemOrderSetup
            where METInventItemOrderSetup.ItemId == this.ItemId
            &&    METInventItemOrderSetup.SiteId == this.inventDim().InventSiteId
            &&    METInventItemOrderSetup.ItemStatus == METConstants::Active).RecID != 0;
}

    /// <summary>
    /// CB167_PerformStockReservation.
    /// Updates reason code.
    /// </summary>
    /// <param name = "_reasonCode">ReasonCode.</param>
    public void metUpdateReasonCode(ReasonCode _reasonCode)
    {
        METSalesLine metSalesLine = this.metSalesLine();

        if (metSalesLine)
        {
            ttsbegin;
            
            metSalesLine.reread();
            metSalesLine.selectForUpdate(true);

            metSalesLine.ReasonId = _reasonCode;
            metSalesLine.update();

            ttscommit;
        }
    }

    /// <summary>
    /// CB167_PerformStockReservation.
    /// Checks if order guide records record exists against <c>SalesLine</c>.
    /// </summary>
    /// <returns>Container containing flags to sell or do not sell.</returns>
    public container metCheckForOrderGuide()
    {
        LogisticsPostalAddress deliveryAddress;
        CustTable              custTable;
        InventDim              inventDim;
        METSalesOrderGuideItem salesOrderGuideType;
        boolean                onlySellTo,
                               doNotSellTo;

        boolean orderGuideRecordNotExist(ItemId _itemId, METSalesOrderGuideReferenceType _referenceType, METSalesOrderGuideReference _reference)
        {
            onlySellTo = METSalesOrderGuideItem::exist(_itemId, _referenceType, _reference, METSalesOrderGuideType::OnlySellTo);
            doNotSellTo =  METSalesOrderGuideItem::exist(_itemId, _referenceType, _reference, METSalesOrderGuideType::DoNotSellTo);
            
            return !onlySellTo && !doNotSellTo;
        }

        if (orderGuideRecordNotExist(this.ItemId, METSalesOrderGuideReferenceType::Customer, this.CustAccount))
        {
            select firstonly METCustOperGroupId from custTable
                where custTable.AccountNum == this.CustAccount;

            if (orderGuideRecordNotExist(this.ItemId, METSalesOrderGuideReferenceType::CustomerOperationsGroup, custTable.METCustOperGroupId))
            {
                select firstonly InventSiteId from inventDim
                    where inventDim.InventDimId == this.InventDimId;

                if (orderGuideRecordNotExist(this.ItemId, METSalesOrderGuideReferenceType::Site, inventDim.InventSiteId))
                {
                    select firstonly State from deliveryAddress
                        where deliveryAddress.RecId == this.DeliveryPostalAddress;

                    orderGuideRecordNotExist(this.ItemId, METSalesOrderGuideReferenceType::State, deliveryAddress.State);
                }
            }
        }

        return [onlySellTo, doNotSellTo];
    }

    /// <summary>
    /// CB223_PalletRounding
    /// </summary>
    /// <param name = "_salesId">Sales order id</param>
    /// <param name = "_itemId">Item number</param>
    /// <param name = "_custAccount">Customer account</param>
    /// <param name = "_salesUnit">Sales order line UOM</param>
    /// <param name = "_inventDimId">Inventory dimension id</param>
    /// <param name = "_applyBonus">apply bonus yes or no</param>
    /// <param name = "_update">select record for update</param>
    /// <returns><c>SalesLine</c> record</returns>
    public static SalesLine metFindBonusStock(SalesId       _salesId,
                                              ItemId        _itemId,
                                              CustAccount   _custAccount,
                                              SalesUnit     _salesUnit,
                                              InventDimId   _inventDimId,
                                              METApplyBonus _applyBonus = NoYes::No,
                                              boolean       _update      = false)
    {
        SalesLine salesLine;
        METSalesLine metSalesLine;

        if (_salesId && _itemId && _custAccount && _salesUnit && _inventDimId)
        {
            if (_update)
            {
                salesLine.selectForUpdate(_update);
            }
            
            select firstonly salesLine
                where salesLine.SalesId == _salesId
                    && salesLine.ItemId == _itemId
                    && salesLine.CustAccount == _custAccount
                    && salesLine.SalesUnit == _salesUnit
                    && salesLine.InventDimId == _inventDimId
                 exists join metSalesLine
                       where metSalesLine.SalesLine == salesLine.RecId
                          && metSalesLine.ApplyBonus == _applyBonus;
        }

        return salesLine;
    }
